INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_hud-lidova-hudba_0','Co je lidová píseň?',ARRAY['Píseň složená pro operu','Chorál v kostele','Píseň z rozhlasu','Píseň vzniklá mezi lidem a předávaná ústně']::TEXT[],3,'Lidové písně se předávají po generace.',1,ARRAY[]::TEXT[],NULL,0,'c_hud-lidova-hudba',NULL,NOW()),
('q_hud-lidova-hudba_1','Jak se jmenuje tanec z Čech, který tančí dvě páry v kruhu?',ARRAY['Tango','Valčík','Polka','Menuet']::TEXT[],2,'Polka je český lidový tanec v rychlém dvoudobém rytmu.',1,ARRAY[]::TEXT[],NULL,1,'c_hud-lidova-hudba',NULL,NOW()),
('q_hud-lidova-hudba_2','Který tanec je typicky moravský a známý ze Slovácka?',ARRAY['Mazurka','Čardáš','Verbuňk','Kankán']::TEXT[],2,'Verbuňk je tanec z jižní Moravy.',2,ARRAY[]::TEXT[],NULL,2,'c_hud-lidova-hudba',NULL,NOW()),
('q_hud-lidova-hudba_3','Jak se nazývá strunný nástroj tlučený paličkami, typický pro cimbálovou muziku?',ARRAY['Cimbál','Piano','Varhany','Harfa']::TEXT[],0,'Cimbál je strunný nástroj tlučený paličkami.',2,ARRAY[]::TEXT[],NULL,3,'c_hud-lidova-hudba',NULL,NOW()),
('q_hud-lidova-hudba_4','Jaké je hlavní téma většiny lidových písní?',ARRAY['Válka a politika','Vesmír','Práce, láska, rok a příroda','Jen náboženství']::TEXT[],2,'Lidové písně odrážejí život venkova.',2,ARRAY[]::TEXT[],NULL,4,'c_hud-lidova-hudba',NULL,NOW()),
('q_hud-lidova-hudba_5','Co znamená výraz „zpěv a tanec v kroji“?',ARRAY['Lidové vystoupení v tradičním oděvu','Balet na ledě','Opera v kostýmech','Sborový zpěv v kostele']::TEXT[],0,'Kroj je tradiční lidový oděv.',3,ARRAY[]::TEXT[],NULL,5,'c_hud-lidova-hudba',NULL,NOW()),
('q_hud-lidova-hudba_6','Jaký je typický rytmus polky?',ARRAY['Dvoudobý, rychlý','Synkopický','Bez rytmu','Tříčtvrťový, pomalý']::TEXT[],0,'Polka má rychlé dvoudobé metrum.',3,ARRAY[]::TEXT[],NULL,6,'c_hud-lidova-hudba',NULL,NOW()),
('q_hud-lidova-hudba_7','Který skladatel se věnoval sběru lidových písní na Moravě?',ARRAY['Bedřich Smetana','Josef Suk','Antonín Dvořák','Leoš Janáček']::TEXT[],3,'Janáček zapisoval moravské lidové písně.',3,ARRAY[]::TEXT[],NULL,7,'c_hud-lidova-hudba',NULL,NOW()),
('q_hud-lidova-hudba_8','Kdo složil hudbu k písni „Kde domov můj“?',ARRAY['Bedřich Smetana','Antonín Dvořák','Leoš Janáček','František Škroup']::TEXT[],3,'Hudbu k Kde domov můj složil František Škroup, text napsal Josef Kajetán Tyl.',3,ARRAY[]::TEXT[],NULL,8,'c_hud-lidova-hudba',NULL,NOW()),
('q_hud-lidova-hudba_9','Co je to tradiční lidový nástroj dudy?',ARRAY['Klávesový nástroj','Smyčcový nástroj','Dechový nástroj s měchem','Bicí nástroj']::TEXT[],2,'Dudy mají vak se vzduchem a píšťalu.',4,ARRAY[]::TEXT[],NULL,9,'c_hud-lidova-hudba',NULL,NOW()),
('q_hud-lidova-hudba_10','Které české hudební těleso hraje lidovou hudbu?',ARRAY['Symfonický orchestr','Dechový kvintet','Cimbálová muzika','Jazzový kvartet']::TEXT[],2,'Cimbálová muzika hraje na cimbál, housle, basy.',4,ARRAY[]::TEXT[],NULL,10,'c_hud-lidova-hudba',NULL,NOW()),
('q_hud-lidova-hudba_11','Co je to zpěvník?',ARRAY['Nástroj na doprovod','Taneční kroky','Kniha se zapsanými písněmi a notami','Druh tance']::TEXT[],2,'Zpěvník obsahuje texty a melodie písní.',4,ARRAY[]::TEXT[],NULL,11,'c_hud-lidova-hudba',NULL,NOW()),
('q_hud-lidova-hudba_12','Jak se říká písni, která vypráví příběh?',ARRAY['Balada','Kantáta','Ária','Hymnus']::TEXT[],0,'Balada je vyprávěcí píseň.',4,ARRAY[]::TEXT[],NULL,12,'c_hud-lidova-hudba',NULL,NOW()),
('q_hud-lidova-hudba_13','Jak se nazývá rozdíl mezi lidovou a uměleckou hudbou?',ARRAY['Není rozdíl','Lidová je anonymní a tradiční, umělecká má autora','Lidová je elektronická','Umělecká je jen instrumentální']::TEXT[],1,'Umělecká hudba má autora a záznam.',5,ARRAY[]::TEXT[],NULL,13,'c_hud-lidova-hudba',NULL,NOW()),
('q_hud-lidova-hudba_14','Co je to „verbuňk“?',ARRAY['Druh opery','Typ piana','Zpěv v chrámu','Tanec z jižní Moravy']::TEXT[],3,'Verbuňk je tanec z jižní Moravy, tančí se v kroji.',5,ARRAY[]::TEXT[],NULL,14,'c_hud-lidova-hudba',NULL,NOW()),
('q_hud-jazz-rock-pop_0','Který styl vznikl v New Orleans na přelomu 19. a 20. století?',ARRAY['Jazz','Opera','Baroko','Gregoriánský chorál']::TEXT[],0,'Jazz vznikl v USA mezi černošskými hudebníky.',1,ARRAY[]::TEXT[],NULL,0,'c_hud-jazz-rock-pop',NULL,NOW()),
('q_hud-jazz-rock-pop_1','Který hudební styl je typický elektrickými kytarami a bicími?',ARRAY['Gregoriánský chorál','Madrigal','Rock','Menuet']::TEXT[],2,'Rock využívá zesílené nástroje.',1,ARRAY[]::TEXT[],NULL,1,'c_hud-jazz-rock-pop',NULL,NOW()),
('q_hud-jazz-rock-pop_2','Jak se říká hudbě, která je krátká a srozumitelná pro široké publikum?',ARRAY['Symfonie','Oratorium','Opera','Pop']::TEXT[],3,'Pop je zkratka populární hudby.',1,ARRAY[]::TEXT[],NULL,2,'c_hud-jazz-rock-pop',NULL,NOW()),
('q_hud-jazz-rock-pop_3','Co je to improvizace v jazzu?',ARRAY['Spontánní hra během skladby','Hra bez rytmu','Přesně zapsaná část','Opakování první věty']::TEXT[],0,'Jazzoví hudebníci improvizují sóla.',2,ARRAY[]::TEXT[],NULL,3,'c_hud-jazz-rock-pop',NULL,NOW()),
('q_hud-jazz-rock-pop_4','Co je to synkopa?',ARRAY['Zvýšení výšky tónu','Zrychlení tempa','Hra nahlas','Posun přízvuku na slabou dobu']::TEXT[],3,'Synkopa dává rytmu přízvuk mimo takt.',2,ARRAY[]::TEXT[],NULL,4,'c_hud-jazz-rock-pop',NULL,NOW()),
('q_hud-jazz-rock-pop_5','Který nástroj je typický pro jazz a hraje se dechem?',ARRAY['Cimbál','Harfa','Varhany','Saxofon']::TEXT[],3,'Saxofon je dechový nástroj vynalezený Adolphem Saxem.',2,ARRAY[]::TEXT[],NULL,5,'c_hud-jazz-rock-pop',NULL,NOW()),
('q_hud-jazz-rock-pop_6','Jak se nazývá styl vzniklý v jižních státech USA s melancholickou náladou?',ARRAY['Blues','Polka','Barokní fuga','Madrigal']::TEXT[],0,'Blues vyjadřuje smutek a naději.',3,ARRAY[]::TEXT[],NULL,6,'c_hud-jazz-rock-pop',NULL,NOW()),
('q_hud-jazz-rock-pop_7','Kdo je znám jako „král rock and rollu“?',ARRAY['Louis Armstrong','Glenn Miller','Elvis Presley','Frank Sinatra']::TEXT[],2,'Elvis Presley popularizoval rock and roll v 50. letech.',3,ARRAY[]::TEXT[],NULL,7,'c_hud-jazz-rock-pop',NULL,NOW()),
('q_hud-jazz-rock-pop_8','Který styl se objevil v 60. letech jako reakce na konzumní hudbu a často měl protestní texty?',ARRAY['Folk / protestní píseň','Opera','Barok','Dixieland']::TEXT[],0,'Folkové písně komentovaly společnost.',3,ARRAY[]::TEXT[],NULL,8,'c_hud-jazz-rock-pop',NULL,NOW()),
('q_hud-jazz-rock-pop_9','Který nástroj přinesl do rocku zesílení?',ARRAY['Cembalo','Lesní roh','Kontrabas','Elektrická kytara']::TEXT[],3,'Elektrická kytara dala rocku hlasitost a zkreslení.',3,ARRAY[]::TEXT[],NULL,9,'c_hud-jazz-rock-pop',NULL,NOW()),
('q_hud-jazz-rock-pop_10','Jak se nazývá tanečně zaměřený jazz z 30. let?',ARRAY['Polonéza','Swing','Rumba','Tango']::TEXT[],1,'Swing je tanečně zaměřený jazz.',4,ARRAY[]::TEXT[],NULL,10,'c_hud-jazz-rock-pop',NULL,NOW()),
('q_hud-jazz-rock-pop_11','Které město je často považováno za kolébku moderního jazzu?',ARRAY['Vídeň','New Orleans','Praha','Paříž']::TEXT[],1,'New Orleans je rodištěm jazzu.',4,ARRAY[]::TEXT[],NULL,11,'c_hud-jazz-rock-pop',NULL,NOW()),
('q_hud-jazz-rock-pop_12','Jaké je hlavní rozdělení populární hudby?',ARRAY['Podle ceny','Podle barvy obalu','Podle stylu, rytmu a nástrojů','Podle barvy kůže']::TEXT[],2,'Styly se liší harmonií, rytmem a nástroji.',4,ARRAY[]::TEXT[],NULL,12,'c_hud-jazz-rock-pop',NULL,NOW()),
('q_hud-jazz-rock-pop_13','Co znamená zkratka „DJ“?',ARRAY['Dance junior','Digital jazz','Duo jamming','Disk jockey']::TEXT[],3,'DJ přehrává a mixuje hudbu.',5,ARRAY[]::TEXT[],NULL,13,'c_hud-jazz-rock-pop',NULL,NOW()),
('q_hud-jazz-rock-pop_14','Jak se nazývá elektronický styl vzniklý z disca a techna?',ARRAY['EDM / elektronická taneční hudba','Symfonická báseň','Madrigal','Gregoriánský chorál']::TEXT[],0,'EDM zahrnuje techno a house.',5,ARRAY[]::TEXT[],NULL,14,'c_hud-jazz-rock-pop',NULL,NOW()),
('q_hud-opera-muzikal_0','Co je opera?',ARRAY['Divadelní představení, kde se zpívá','Tanec bez hudby','Hra bez zpěvu','Film pro děti']::TEXT[],0,'Opera spojuje zpěv, orchestr a divadlo.',1,ARRAY[]::TEXT[],NULL,0,'c_hud-opera-muzikal',NULL,NOW()),
('q_hud-opera-muzikal_1','Jak se nazývá sólová píseň v opeře?',ARRAY['Motet','Fuga','Kantáta','Árie']::TEXT[],3,'Árie je sólový zpěv s doprovodem.',1,ARRAY[]::TEXT[],NULL,1,'c_hud-opera-muzikal',NULL,NOW()),
('q_hud-opera-muzikal_2','Která česká opera je nejznámější od Bedřicha Smetany?',ARRAY['Její pastorkyňa','Prodaná nevěsta','Rusalka','Carmen']::TEXT[],1,'Prodaná nevěsta je veselohra.',2,ARRAY[]::TEXT[],NULL,2,'c_hud-opera-muzikal',NULL,NOW()),
('q_hud-opera-muzikal_3','Která opera Antonína Dvořáka je založena na vodní víle?',ARRAY['Libuše','Rusalka','Otello','Prodaná nevěsta']::TEXT[],1,'Rusalka je pohádková opera.',2,ARRAY[]::TEXT[],NULL,3,'c_hud-opera-muzikal',NULL,NOW()),
('q_hud-opera-muzikal_4','Který skladatel složil operu „Její pastorkyňa“?',ARRAY['Josef Suk','Bedřich Smetana','Antonín Dvořák','Leoš Janáček']::TEXT[],3,'Její pastorkyňa je Janáčkova opera.',2,ARRAY[]::TEXT[],NULL,4,'c_hud-opera-muzikal',NULL,NOW()),
