('q_hud-opera-muzikal_6','Který skladatel složil operetu „Netopýr“?',ARRAY['Richard Wagner','Wolfgang Amadeus Mozart','Giuseppe Verdi','Johann Strauss mladší']::TEXT[],3,'Netopýr je vídeňská operetta.',3,ARRAY[]::TEXT[],NULL,6,'c_hud-opera-muzikal',NULL,NOW()),
('q_hud-opera-muzikal_7','Co je muzikál?',ARRAY['Hudba bez textu','Opera o zvířatech','Sbor bez doprovodu','Divadelní žánr, kde se střídá zpěv a mluvené slovo a tanec']::TEXT[],3,'Muzikál spojuje zpěv, tanec a dialog.',3,ARRAY[]::TEXT[],NULL,7,'c_hud-opera-muzikal',NULL,NOW()),
('q_hud-opera-muzikal_8','Který muzikál je inspirovaný románem Victora Huga?',ARRAY['Cats','Chicago','Les Misérables','Hamilton']::TEXT[],2,'Les Misérables vychází z románu Bídníci.',3,ARRAY[]::TEXT[],NULL,8,'c_hud-opera-muzikal',NULL,NOW()),
('q_hud-opera-muzikal_9','Co je libreto?',ARRAY['Dirigentská hůl','Text opery nebo muzikálu','Program koncertu','Partitura']::TEXT[],1,'Libreto je text, který zpívají pěvci.',4,ARRAY[]::TEXT[],NULL,9,'c_hud-opera-muzikal',NULL,NOW()),
('q_hud-opera-muzikal_10','Jak se jmenuje hlavní část opery, kde zpívají sbor i sólisté?',ARRAY['Předehra','Preludium','Coda','Finále']::TEXT[],3,'Finále bývá závěrečný dějový oddíl.',4,ARRAY[]::TEXT[],NULL,10,'c_hud-opera-muzikal',NULL,NOW()),
